{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It would replace Section 49-6-2302 so that each local board of education must set up a school lunch program and a school breakfast program. These programs must give a free lunch and breakfast to each enrolled student who is eligible for free or reduced-price meals, under rules set under Section 49-6-2303.",
      "rationale": "Conveys the replacement, responsible boards, required programs, eligible enrolled students, free meals, and governing rules."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Subject to available funding, the state would reimburse each local education agency (LEA) for the cost of a free breakfast and lunch for each student eligible for reduced-price meals. That reimbursement would come only after all available federal funds have been applied. These funds include those from the National School Lunch Act, the Child Nutrition Act of 1966 school breakfast program, or any other federal program.",
      "rationale": "Conveys state reimbursement to LEAs for the specified meals and eligibility group, conditioned on available funding and prior application of all available federal funds. The enrolled-student scope is established by the preceding program description."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill would also amend Section 49-6-2303 by deleting the words \", regardless of its participation\" in subdivision (5) and by deleting subdivision (10).",
      "rationale": "Identifies the exact language deleted and the statutory subdivision affected."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would also amend Section 49-6-2303 by deleting the words \", regardless of its participation\" in subdivision (5) and by deleting subdivision (10).",
      "rationale": "Explicitly identifies deletion of Section 49-6-2303(10)."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "In Section 49-2-114(a), it would replace \"receive free or reduced-price school lunches\" with wording about students who are members of households with an income that meets the eligibility requirements for free or reduced-price lunch under 42 U.S.C. § 1758.",
      "rationale": "Identifies the amended provision and the change from meal receipt to household-income eligibility under the specified federal standard."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025, and would apply to the 2025-2026 school year and each school year after that.",
      "rationale": "States both the effective date and application to the specified school year and all subsequent school years."
    }
  ]
}
